    }

    function testSmallTransferPaysNoFee() public {
        // Check initial balances
        uint256 ownerInitialBalance = token.balanceOf(owner);
        uint256 feeAddressInitialBalance = token.balanceOf(feeAddress);

        // Transfer amount < 10000 (which would result in 0 fee)
        uint256 smallAmount = 9_999;
        token.transfer(recipient, smallAmount);

        // Verify recipient received full amount
        assertEq(token.balanceOf(recipient), smallAmount);

        // Verify fee address received no tokens
        assertEq(token.balanceOf(feeAddress), feeAddressInitialBalance);

        // Verify owner balance reduced by only the transfer amount
        assertEq(
            token.balanceOf(owner), 
            ownerInitialBalance - smallAmount,
            "Owner balance not reduced by exact transfer amount"
        );
    }
}
